 * time: 2019/03/24
 * disclaimer: 插件修改于明月浩空免费版，仅用于学习交流，无商业价值
 *             如发现商业传播，将禁止软件的免费使用
 */

/* 声明全局变量 */
:root {
    --player-width: 350px;
    --cover-width:115px;
}
#lzxPlayer {
    margin: 0;
    font: small 'Microsoft Yahei'
}

ul, li {
    margin: 0;
    padding: 0;
    list-style: none
}

.ts5 {
    -webkit-transition: .5s;
    -moz-transition: .5s;
    -ms-transition: .5s;
    transition: .5s
}

#lzxPlayer {
    -webkit-transition: .5s;
    -moz-transition: .5s;
    -ms-transition: .5s;
    transition: .5s;
    left: 345px;
    left: calc(var(--player-width) * -1);
    text-align: left;
    color: #38343e;
    width: 345px;
    width: var(--player-width);
    position: fixed;
    bottom: 40px;
    box-shadow: 0 0 5px 5px rgba(0, 0, 0, 0.2);
    border-radius: 5px;
    z-index: 999;
    margin: 0;
    padding: 0;
    list-style: none;
    font-family: "Microsoft YaHei", "微软雅黑", "Trebuchet MS", Arial, Verdana, Tahoma, sans-serif;
}

#lzxPlayer .player {
    position: relative;
    overflow: hidden;
    text-shadow: none;
    background-color: rgba(0, 0, 0, 0.1);
    height: 180px;
    border-radius: 5px 5px 0 0
}

#lzxPlayer .player .cover {
    -webkit-user-select: none;
    -moz-user-select: none;
    -ms-user-select: none;
    user-select: none;
    position: absolute;
    background-color: #fff;
    width: 115px;
    height: 115px;
    width: var(--cover-width);
    height: var(--cover-width);
    top: 50%;
    left: 50%;
    border-radius: 50%;
    box-shadow: 0 0 20px rgba(0, 0, 0, 0.3);
    margin-top: -67.5px;
    margin-left: -57.5px;
    margin-top: calc(var(--cover-width) / -2 - 10px);
    margin-left: calc(var(--cover-width) / -2);
}

#lzxPlayer .player .cover:after {
    content: 'ILT.ME';
    position: absolute;
    opacity: .5;
    width: 100%;
    left: 0;
    text-align: center;
    top: 45px
}

#lzxPlayer .player .cover.changing img {
    -webkit-transform: scale(0.3);
    -moz-transform: scale(0.3);
    -ms-transform: scale(0.3);
    transform: scale(0.3);
    opacity: 0
}

#lzxPlayer .player .cover img {
    -webkit-transition: .5s;
    -moz-transition: .5s;
    -ms-transition: .5s;
    transition: .5s;
    border-radius: 50%;
    border: 3px #fff solid;
    width: 118px;
    height: 118px;
    width: calc(var(--cover-width) + 3px);
    height: calc(var(--cover-width) + 3px);
    top: -5px;
    left: -5px;
    position: relative;
    z-index: 10;
}

#lzxPlayer .player .infos {
    position: absolute;
    top: 10px;
    color: #fff;
    width: 100%;
    padding: 0 10px;
    box-sizing: border-box;
}

#lzxPlayer .player .infos .artiststyle {
    margin-top: 15px
}

#lzxPlayer .player .infos .moshi {
    float: right
}

#lzxPlayer .player .infos .geci {
    float: right
}

#lzxPlayer .player .infos .timestyle {
    font-size: 12px;
    margin-left: 255px;
    margin-top: -20px
}

#lzxPlayer .player .control {
    -webkit-user-select: none;
    -moz-user-select: none;
    -ms-user-select: none;
    user-select: none;
    bottom: 30px;
    text-shadow: none;
    position: absolute;
    z-index: 99999;
    font-size: 1.8em;
    color: #fff;
    padding: 0 70px;
    height: 40px;
    overflow: auto;
    width: 100%;
    box-sizing: border-box;
}

#lzxPlayer .player .control .loop, #lzxPlayer .player .control .prev{
    margin-right: 25px;
    cursor: url(player.cur), pointer;
    color: inherit;
}

#lzxPlayer .player .control .next,#lzxPlayer .player .control .random{
    margin-left: 25px;
    cursor: url(player.cur), pointer;
    color: inherit;
}

#lzxPlayer .player .control i.current {
    color: #81c300
}

#lzxPlayer .player .control .next {
    position: relative;
    display: inline-block;
    vertical-align: middle;
}

#lzxPlayer .player .control .next:hover {
    color: #81c300
}

#lzxPlayer .player .control .loop:hover {
    color: #81c300
}

#lzxPlayer .player .control .prev:hover {
    color: #81c300
}

#lzxPlayer .player .control .random {
    position: relative;
    display: inline-block;
    vertical-align: middle;
}

#lzxPlayer .player .control .random:hover {
    color: #81c300
}

#lzxPlayer .player .status {
    display: inline-block;
    vertical-align: middle;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background-color: #81c300;
    background-image: linear-gradient(90deg, #6c6971 50%, transparent 50%, transparent), linear-gradient(90deg, #81c300 50%, #6c6971 50%, #6c6971);
    position: absolute;
    left: 50%;
    top: 50%;
    z-index: 99999;
    margin-top: -32px;
    margin-left: -22px;
    font-size: 20px;
    cursor: url(player.cur), pointer;
}

#lzxPlayer .player .status b {
    position: absolute;
    width: 40px;
    height: 40px;
    text-align: center;
    border: solid #f30 2px;
    top: 0;
    left: 0;
    border-radius: 50%;
    background-color: #2c2a30;
    display: inline-block;
    overflow: hidden
}

#lzxPlayer .player .status b .fa {
    display: block;
    width: 40px;
    height: 40px;
    line-height: 40px
}

#lzxPlayer .player .status b .fa:hover {
    color: #f30
}

#lzxPlayer .player .status b .play {
    color: #f30;
    -webkit-transition: .5s;
    -moz-transition: .5s;
    -ms-transition: .5s;
    transition: .5s
}

#lzxPlayer .player .status b .play:hover {
    color: #81c300
}

#lzxPlayer .player .status b .pause {
    -webkit-transition: .5s;
    -moz-transition: .5s;
    -ms-transition: .5s;
    transition: .5s
}

#lzxPlayer .player .status b .pause:hover {
    color: #81c300
}

#lzxPlayer .player .musicbottom {
    -webkit-user-select: none;
    -moz-user-select: none;
    -ms-user-select: none;
    user-select: none;
    position: absolute;
    background-color: #fff;
    text-shadow: none;
    height: 25px;
    width: 100%;
    left: 0;
    bottom: 0;
    line-height: 25px;
    display: flex;
}

/*进度开始----------------------------------------------------*/
#lzxPlayer .player .musicbottom .rate {
    color: #cccbce;
    height: 100%;
    position: relative;
    overflow: hidden;
    display: inline-block;
    padding-left: 15px;
    box-sizing: border-box;
    flex: 1;
    padding-right: 10px;
}
#lzxPlayer .player .musicbottom .icons{
    display: inline-block;
    width:100px
}
#lzxPlayer .player .musicbottom .rate .mute {
    float: left
}

#lzxPlayer .player .musicbottom .rate .volumeup {
    float: right
}

#lzxPlayer .player .musicbottom .rate .progress {
    position: relative;
    width: 100%;
    background-color: #b0aeb2;
    overflow: visible;
    vertical-align: middle;
    display: inline-block;
    height: 5px;
    border-radius: 2px;
    margin: auto;
}

#lzxPlayer .player .musicbottom .rate .progress .rate-on {
    position: relative;
    background-color: #81c300;
    width: 0;
    height: 100%;
}

#lzxPlayer .player .musicbottom .rate .progress .rate-on .drag {
    width: 16px;
    height: 16px;
    position: absolute;
    top: -6px;
    right: -5px;
    background-color: #fff;
    border-radius: 50%;
    box-shadow: 0 0 1px 1px rgba(0, 0, 0, 0.2);
    cursor: url(player.cur), pointer;
}
#lzxPlayer.phone .player .musicbottom .rate .progress .rate-on .drag{
    width: 18px;
    height: 18px;
    top: -7px;
    right: -9px;
}
#lzxPlayer .musicbottom .rate-buffered{
    position: absolute;
    width: 0;
    background-color: #777777;
    height: 100%;
    top: 0;
    transition-duration: .5s;
    transition-property: width;
    transition-timing-function: ease;
    border-radius:2px;
}
/*进度结束----------------------------------------------------*/

#lzxPlayer .player .musicbottom .volume {
    position: absolute;
    left: 6px;
    top: 6px;
    color: #cccbce
}

#lzxPlayer .player .musicbottom .volume .mute {
    float: left
}

#lzxPlayer .player .musicbottom .volume .volumeup {
    float: right
}

#lzxPlayer .player .musicbottom .volume .progress {
    position: relative;
    width: 145px;
    margin: 0 15px;
    margin-top: 4.5px;
    height: 3px;
    background-color: #b0aeb2;
    overflow: visible;
}

#lzxPlayer .player .musicbottom .volume .progress .volume-on {
    position: relative;
    background-color: #81c300;
    width: 0;
    height: 3px
}

#lzxPlayer .player .musicbottom .volume .progress .volume-on .drag {
    width: 14px;
    height: 14px;
    position: absolute;
    top: -5px;
    right: -5px;
    background-color: #fff;
    border-radius: 50%;
    box-shadow: 0 0 1px 1px rgba(0, 0, 0, 0.2);
    cursor: url(player.cur), pointer
}

#lzxPlayer .player .musicbottom .switch-playlist {
    float: right;
    -webkit-transition: .5s;
    -moz-transition: .5s;
    -ms-transition: .5s;
    transition: .5s;
    cursor: url(player.cur), pointer;
    width: 25px;
    text-align: center;
}

#lzxPlayer .player .musicbottom .switch-playlist:hover {
    color: #81c300
}

#lzxPlayer .player .musicbottom .switch-ksclrc {
    -webkit-transition: .5s;
    -moz-transition: .5s;
    -ms-transition: .5s;
    transition: .5s;
    right: 35px;
    font-size: 1.2em;
    cursor: url(player.cur), pointer;
    width: 25px;
    float: right;
    text-align: center;
}

#lzxPlayer .player .musicbottom .switch-ksclrc:hover {
    color: #81c300
}

#lzxPlayer .player .musicbottom .new-volume {
    -webkit-transition: .5s;
    -moz-transition: .5s;
    -ms-transition: .5s;
    transition: .5s;
    font-size: 1.2em;
    cursor: url(player.cur), pointer;
    width: 25px;
    float: right;
    text-align: center;
    position: relative;
}

#lzxPlayer .player .musicbottom .new-volume:hover {
    color: #81c300
}

#lzxPlayer .player .musicbottom .switch-default {
    position: absolute;
    -webkit-transition: .5s;
    -moz-transition: .5s;
    -ms-transition: .5s;
    transition: .5s;
    top: 6px;
    line-height: 10px;
