}

#lzxPlayer:hover .status {
    opacity: 1;
    filter: alpha(opacity=100)
}

#tooltip {
    position: absolute;
    z-index: 9999;
    display: none;
    padding: 4px 8px;
    border: 1px solid rgba(255, 255, 255, 0.25);
    border-radius: 3px;
    background-color: #0c0;
    color: #fff;
    text-align: center;
    font-size: 12px
}

#tooltip:before {
    position: absolute;
    top: -6px;
    left: 15px;
